      "mainEntity": [
        {
          "@type": "Question",
          "name": "Do you supply the toilet and remove the old one?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. The agreed installation package includes the selected toilet, removal and taking away the old unit. The written quote identifies the product and any additional connection or access work."
          }
        },
        {
          "@type": "Question",
          "name": "Can a running toilet be repaired without replacing the whole toilet?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Often the fault needs assessment of cistern components rather than an immediate new suite. We explain the findings and available repair or replacement scope before you approve the work."
          }
        },
        {
          "@type": "Question",
          "name": "Does a blocked toilet mean I need a new toilet?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. A blockage, a cistern fault and a damaged toilet suite are different problems. Drainage needs assessment where water backs up or other outlets are affected; replacing a suite does not automatically clear a downstream blockage."
          }
        },
        {
          "@type": "Question",
          "name": "Can I choose the toilet myself?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, but confirm compatibility before ordering. Waste and water connection positions, dimensions and access can affect whether the selected model suits the existing installation."
          }
        }
      ]
